// The sound of the book: a small Web Audio engine. main.js calls its events (pageTurn, choice,
// riffle, arrive ...); what plays where is in soundscape.js, the files and their variants in
// sounds.js (generated by scripts/sfx/master.mjs), the mix in LEVELS below.
//
// The design (2026-10-25, after the user read both tales with sound): immersion in the tale's world
// while reading calmly, never a pile of sounds at a page turn.
// - One bed at a time, continuous: the reading room's hearth on title spreads, the place of the
//   story on its pages (soundscape.js). It changes only with the place or the time of day, by a long
//   slow crossfade (BED_FADE) that starts once the new page has landed; it never restarts per page.
// - Over the bed, at most one foreground sound at any moment: a page turn (or riffle), a choice, a
//   theme, a language rewrite, or one spot sound. Nothing fires as a page lands; a page's spot sounds
//   come some seconds after it has settled, and wait while anything else is sounding. A turn stops
//   them. A theme lowers the bed while it plays; a tale's opening theme rings on to its end across
//   the turns of its tale, with the place of its first page rising beneath it (soundscape.js, the
//   opening), and fades only for another tale, "Begin again" or the sound turned off; a closing
//   theme fades with a turn.
// - Every control clicks with the same warm click (the clasp's); a choice is the soft press of the
//   wax seal and, in the same breath, the harp in D.
//
// Mechanics:
// - Nothing plays before a gesture: attach() listens (capture phase, so it runs before the book's
//   own handlers) for pointerup / touchend / click / keydown and resumes the context inside it;
//   it stays attached, so a context iOS suspended (call, Siri, lock screen) resumes on the next touch.
//   Files are fetched and decoded ahead (an OfflineAudioContext needs no gesture), so the very first
//   page turn already sounds.
// - iPhone/iPad Silent mode is respected (audio session "ambient" where Safari offers it): the book
//   never overrides it and mixes with other audio rather than stopping it.
// - Buses: ui (the click), sfx (paper, wax, quill), music (harp, themes), amb (the bed and its spot
//   sounds), each with its own ducking gain, into a master with a soft limiter.
// - Opus (WebM) where it decodes, AAC (M4A) otherwise (Safari), chosen by decoding a tiny probe.
// - Hidden tab: faded and suspended. Five minutes without a touch: the bed fades away until the next.
// - Reduced motion is the caller's business: pageTurn / riffle take `reduced` and pick the shorter
//   sounds that match the crossfade; nothing here reads the media query.
import { SOUND_BASE, sounds as MANIFEST } from "./sounds.js";
import { ROOM, sceneFor, taleIds } from "./soundscape.js";

// The mix, in dB against the files' common level (one-shots are mastered to -20 LUFS momentary max,
// beds to -24 LUFS integrated). Foreground sounds sit together around a quiet page turn; spot sounds
// lower, as part of the place; the bed gently audible under the reading.
export const LEVELS = {
  // the turn of a page and the riffle: quiet foley
  "page-turn": -8, "page-settle": -11, "page-held": -12, "riffle-leaf": -13, "riffle-land": -9, "ribbon-silk": -13, "pages-return": -10,
  // a choice: the wax just under the harp, one gesture
  "seal-press": -12, "choice-motif": -5,
  "quill-rewrite": -12, "cover-open": -7, "cover-land": -8,
  // the tales' themes (the bed steps back while they play)
  "dragon-intro-theme": -8, "dragon-ending-theme": -8, "bell-intro-theme": -8, "bell-ending-theme": -8, "motif-end": -8,
  // the one click of every control
  clasp: -14,
  // spot sounds: the bell a little nearer, the far bell and the candle further
  "mh-bell": -10, "mh-bell-far": -15, "candle-sputter": -17,
};
const SPOT_DB = -15; // any other spot sound
export const BED_DB = { place: -18, room: -22, themeDuck: -6 };
const BED_FADE = 9; // s: the crossfade of a new place or time of day
const THEME_COOLDOWN = 120; // s before a tale's theme plays again for the same page
const THEME_FADE = 2; // s: a theme giving way (another tale, "Begin again", a turn off the last page)
const TONAL = new Set(["choice-motif", "motif-end", "mh-bell", "mh-bell-far", "mh-bronze", "mh-hum", "dragon-intro-theme", "dragon-ending-theme", "bell-intro-theme", "bell-ending-theme"]);
const MAX_VOICES = { "page-turn": 2, "quill-rewrite": 1, "choice-motif": 2, "motif-end": 1, "riffle-leaf": 6 };
const BUSES = ["ui", "sfx", "story", "music", "amb"];
const BUDGET = 48 * 1024 * 1024; // decoded bytes kept (float PCM)
const IDLE_AFTER = 300; // s without a touch before the bed fades
// The safety limiter: only ever there for a sum that would clip. A DynamicsCompressor adds a fixed
// make-up gain of its own (1.7 dB with these settings, measured in Chromium and WebKit, 2026-10-25),
// taken off again before it, so below its threshold the mix passes at unity. (Before: threshold
// -6 dB, ratio 12, knee 4 added 2.6 dB to everything and crushed every peak over -6 dBFS.)
const LIMITER = { threshold: -3, knee: 0, ratio: 20, attack: 0.002, release: 0.2, makeup: 1.7 };
const HEADROOM = -6; // dBFS: no single sound, made up or not, peaks above this
// 60 ms of silence in Opus/WebM: if this decodes, so do the .webm files
const OPUS_PROBE = "data:audio/webm;base64,";

// the core sounds wanted first (preloadCore): the gate's click, the cover opening and landing, the page
const FIRST = ["clasp", "cover-open", "cover-land", "page-turn", "page-settle"];
const dbGain = (db) => Math.pow(10, db / 20);
const gainDb = (g) => +(20 * Math.log10(Math.max(g, 1e-6))).toFixed(1);
const rnd = (a, b) => a + Math.random() * (b - a);
const now = () => performance.now() / 1000;

export function createSound({ base = "/", enabled = true, onChange = null, debug = false } = {}) {
  const AC = window.AudioContext || window.webkitAudioContext;
  const OAC = window.OfflineAudioContext || window.webkitOfflineAudioContext;
  const S = {
    on: Boolean(enabled), ctx: null, unlocked: false, master: null, buses: {}, ducks: {},
    files: new Map(), // file -> { buffer, bytes, last, promise }
    bags: new Map(), voices: [], bed: null, spot: null, spots: [], spotVoices: [], theme: null, themesHeard: new Map(),
    want: null, // the bed where the reader is calls for, kept while the sound is off (restartBed brings it up)
    opening: null, // a tale's opening: { tale, bed, risen, timer, due (context s) } while its theme sounds
    fading: [], // debug only: voices fading out, { id, g, until (context s), fade }
    fgUntil: 0, // until when a foreground sound plays (performance seconds)
    history: [], // debug only: every sound started, { t (performance s), id, file }
    lastInput: now(), idle: false, hold: 0, queue: [], lanes: 0, attached: false,
  };
  const log = (...a) => debug && console.info("[sound]", ...a);
  const supported = Boolean(AC);

  // ---------------------------------------------------------------- decoding (works before the gesture)
  let offline = null;
  const decoder = () => S.ctx || (offline ||= OAC ? new OAC(2, 1, 48000) : null);
  const decode = (ab) =>
    new Promise((resolve, reject) => {
      const d = decoder();
      if (!d) return reject(new Error("no Web Audio"));
      const p = d.decodeAudioData(ab, resolve, reject); // the callback form for older Safari
      if (p && p.then) p.then(resolve, reject);
    });
  const formatReady = supported
    ? fetch(OPUS_PROBE).then((r) => r.arrayBuffer()).then(decode).then(() => "webm", () => "m4a")
    : Promise.resolve(null);
  formatReady.then((f) => log("format", f));
  const urlOf = (file, ext) => `${base}${SOUND_BASE.replace(/^\//, "")}${file}.${ext}`;

  function load(file, pin = false) {
    let f = S.files.get(file);
    if (f) {
      f.last = now();
      if (pin) f.pin = true;
      return f.promise;
    }
    f = { buffer: null, bytes: 0, last: now(), pin };
    f.promise = formatReady
      .then((ext) => fetch(urlOf(file, ext)))
      .then((r) => {
        if (!r.ok) throw new Error(`${r.status} ${file}`);
        return r.arrayBuffer();
      })
      .then(decode)
      .then((buffer) => {
        f.buffer = buffer;
        f.bytes = buffer.length * buffer.numberOfChannels * 4;
        evict();
        return buffer;
      })
      .catch((e) => {
        S.files.delete(file);
        log("load failed", file, e.message);
        return null;
      });
    S.files.set(file, f);
    return f.promise;
  }
  function evict() {
    let total = [...S.files.values()].reduce((a, f) => a + f.bytes, 0);
    const keep = new Set([S.bed?.file].filter(Boolean));
    for (const [file, f] of [...S.files.entries()].sort((a, b) => a[1].last - b[1].last)) {
      if (total <= BUDGET) break;
      if (f.pin || keep.has(file) || !f.buffer) continue;
      S.files.delete(file);
      total -= f.bytes;
    }
  }
  const filesOf = (id) => (MANIFEST[id]?.variants || []).map((v) => v.file);
  // loaded two at a time (on a slow line each file costs a round trip more than its bytes), never
  // while a leaf is in the air (a decode on the main thread would cost a frame)
  const LANES = 2;
  function enqueue(ids, pin = false) {
    if (!S.on || !supported) return; // a silent book downloads nothing
    for (const id of ids) for (const file of filesOf(id)) if (!S.files.has(file) && !S.queue.some((q) => q.file === file)) S.queue.push({ file, pin });
    pump();
  }
  function pump() {
    for (; S.lanes < LANES && S.queue.length; S.lanes++) lane();
  }
  function lane() {
    if (!S.queue.length) return void S.lanes--;
    if (now() < S.hold) return void setTimeout(lane, (S.hold - now()) * 1000 + 50);
    const { file, pin } = S.queue.shift();
    load(file, pin).then(() => setTimeout(lane, 30));
  }
  const groupIds = (group) => Object.keys(MANIFEST).filter((id) => MANIFEST[id].group === group);

  // ---------------------------------------------------------------- the context and its buses
  function build() {
    if (S.ctx || !supported) return;
    try {
      if (navigator.audioSession) navigator.audioSession.type = "ambient";
    } catch {}
    S.ctx = new AC({ latencyHint: "interactive" });
    const ctx = S.ctx;
    S.master = ctx.createGain();
    S.master.gain.value = S.on ? 1 : 0;
    const trim = ctx.createGain();
    trim.gain.value = dbGain(-LIMITER.makeup);
    const lim = ctx.createDynamicsCompressor();
    lim.threshold.value = LIMITER.threshold;
    lim.knee.value = LIMITER.knee;
    lim.ratio.value = LIMITER.ratio;
    lim.attack.value = LIMITER.attack;
    lim.release.value = LIMITER.release;
    S.master.connect(trim).connect(lim).connect(ctx.destination);
    if (debug) {
      // the mix measured just before the limiter (its peak shows whether the limiter would act) and
      // as it leaves the book: the worst of each since the start
      const meter = (node) => {
        const an = ctx.createAnalyser();
        an.fftSize = 2048;
        node.connect(an);
        return { an, buf: new Float32Array(an.fftSize) };
      };
      const pre = meter(trim), post = meter(lim);
      S.meter = { pre: -120, post: -120 };
      const peakOf = ({ an, buf }) => {
        an.getFloatTimeDomainData(buf);
        let p = 0;
        for (const x of buf) p = Math.max(p, Math.abs(x));
        return 20 * Math.log10(p + 1e-9);
      };
      setInterval(() => {
        S.meter.pre = Math.max(S.meter.pre, peakOf(pre));
        S.meter.post = Math.max(S.meter.post, peakOf(post));
      }, 40);
    }
    for (const b of BUSES) {
      const level = ctx.createGain();
      const duck = ctx.createGain();
      level.connect(duck).connect(S.master);
      S.buses[b] = level;
      S.ducks[b] = duck;
    }
    ctx.onstatechange = () => log("context", ctx.state);
    log("context built", ctx.sampleRate, "Hz");
  }

  // Inside a gesture: build or resume the context; the first time, the bed of where the reader is.
  function unlock() {
    S.lastInput = now();
    if (S.idle) wake();
    if (!S.on || !supported) return;
    build();
    const ctx = S.ctx;
    if (ctx.state !== "running" && !document.hidden) ctx.resume().catch(() => {});
    if (!S.unlocked) {
      // one silent sample started inside the gesture: older iOS only opens the output this way
      const src = ctx.createBufferSource();
      src.buffer = ctx.createBuffer(1, 1, ctx.sampleRate);
      src.connect(ctx.destination);
      src.start(0);
      S.unlocked = true;
      restartBed(4);
      log("unlocked");
    }
  }
  function attach(target = window) {
    if (S.attached) return;
    S.attached = true;
    for (const type of ["pointerup", "touchend", "click", "keydown"]) target.addEventListener(type, unlock, { capture: true, passive: true });
    document.addEventListener("visibilitychange", onVisibility);
    window.addEventListener("pagehide", () => S.ctx?.suspend().catch(() => {}));
    setInterval(checkIdle, 20000);
  }
  function onVisibility() {
    if (!S.ctx) return;
    const g = S.master.gain, t = S.ctx.currentTime;
    if (document.hidden) {
      g.cancelScheduledValues(t);
      g.setTargetAtTime(0, t, 0.06);
      setTimeout(() => document.hidden && S.ctx.suspend().catch(() => {}), 300);
    } else if (S.on) {
      S.ctx.resume().catch(() => {}); // iOS may want a touch first: unlock() resumes on the next one
      g.cancelScheduledValues(t);
      g.setTargetAtTime(1, t, 0.2);
    }
  }
  const ready = () => Boolean(S.on && S.ctx && S.unlocked && !document.hidden);

  // ---------------------------------------------------------------- one-shots
  function pickVariant(id, slot) {
    const list = MANIFEST[id].variants;
    let pool = list.map((v, i) => i);
    if (slot) {
      const roled = pool.filter((i) => list[i].role === slot);
      if (roled.length) pool = roled;
    }
    if (pool.length === 1) return list[pool[0]];
    // a shuffled bag per id and slot: every variant before any repeats, never the same twice running
    const key = `${id}|${slot || ""}`;
    let bag = S.bags.get(key);
    if (!bag || !bag.left.length) {
      const left = [...pool].sort(() => Math.random() - 0.5);
      if (bag && left[0] === bag.prev && left.length > 1) left.push(left.shift());
      bag = { left, prev: bag?.prev };
      S.bags.set(key, bag);
    }
    const i = bag.left.shift();
    bag.prev = i;
    return list[i];
  }
  const levelOf = (id, entry, bus) => LEVELS[id] ?? (bus === "amb" && entry.kind !== "bed" ? SPOT_DB : 0);
  // A file the peak ceiling held under the common level (sounds.js `lufs`, `tp`; files without them
  // are at it): made up here, never so far that its peak would pass HEADROOM (a peaky take, like the
  // cover's, stays quieter than its level rather than reaching the limiter).
  function makeUp(v, level, bed) {
    if (v.lufs === undefined || v.capped) return 0; // a capped bed stays as quiet as it was capped
    return Math.max(0, Math.min((bed ? -24 : -20) - v.lufs, HEADROOM - (v.tp ?? -1) - level));
  }
  // play(id, { when (s from now), gainDb, pan, panTo, panDur, rate, slot, bus, late (s a late load
  // may still start) }) -> a handle { stop(fade), dur, started } (also for a sound still loading;
  // `started` resolves with its voice once it is started, `at` the context time it sounds from, or
  // with null if it never starts), or null (sound off, not unlocked yet, unknown id)
  function play(id, o = {}) {
    const entry = MANIFEST[id];
    if (!entry || !ready()) return null;
    const v = pickVariant(id, o.slot);
    const f = S.files.get(v.file);
    const at = S.ctx.currentTime + 0.005 + (o.when || 0);
    const handle = { id, dur: v.dur, voice: null, cancelled: false, stop: (fade = 0.1) => ((handle.cancelled = true), handle.voice && fadeOut(handle.voice, fade)) };
    if (!f?.buffer) {
      // not decoded yet: start when it is, if that is still close enough to when it was meant
      const late = o.late ?? (entry.bus === "music" ? 1.2 : 0.06);
      handle.started = load(v.file).then((buffer) => {
        if (buffer && !handle.cancelled && S.ctx.currentTime <= at + late) handle.voice = start(id, entry, v, buffer, Math.max(at, S.ctx.currentTime + 0.005), o);
        return handle.voice;
      });
      return handle;
    }
    f.last = now();
    handle.voice = start(id, entry, v, f.buffer, at, o);
    handle.started = Promise.resolve(handle.voice);
    return handle;
  }
  function start(id, entry, v, buffer, at, o) {
    const ctx = S.ctx;
    const bus = o.bus || entry.bus || "sfx";
    const tonal = TONAL.has(id);
    const jit = tonal || bus === "music" ? { r: 0, g: 0 } : bus === "amb" ? { r: 0.02, g: 1.5 } : { r: 0.03, g: 1.5 };
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    src.playbackRate.value = (o.rate || 1) * (1 + rnd(-jit.r, jit.r));
    if (v.detune && src.detune) src.detune.value = v.detune;
    const g = ctx.createGain();
    const lv = levelOf(id, entry, bus) + (entry.gainDb || 0) + (o.gainDb || 0);
    g.gain.value = dbGain(lv + makeUp(v, lv, false) + rnd(-jit.g, jit.g));
    let out = g;
    if ((o.pan || o.panTo) && ctx.createStereoPanner) {
      const p = ctx.createStereoPanner();
      p.pan.setValueAtTime(o.pan || 0, at);
      if (o.panTo !== undefined) p.pan.linearRampToValueAtTime(o.panTo, at + (o.panDur || buffer.duration));
      g.connect(p);
      out = p;
    }
    src.connect(g);
    out.connect(S.buses[bus] || S.buses.sfx);
    src.start(at);
    if (debug) {
      S.history.push({ t: +(now() + (at - ctx.currentTime)).toFixed(3), id, file: v.file });
      if (S.history.length > 400) S.history.shift();
    }
    const voice = { id, src, g, at, end: at + buffer.duration / src.playbackRate.value, keep: Boolean(o.keep) };
    src.onended = () => (S.voices = S.voices.filter((x) => x !== voice));
    // per-sound and overall limits: the oldest gives way, quickly faded (never a theme: it rings on
    // under the turns, and gives way only as playTheme / stopTheme say)
    const same = S.voices.filter((x) => x.id === id);
    if (same.length >= (MAX_VOICES[id] || 3)) fadeOut(same[0], 0.03);
    if (S.voices.length >= 16) {
      const oldest = S.voices.find((x) => !x.keep);
      if (oldest) fadeOut(oldest, 0.03);
    }
    S.voices.push(voice);
    return voice;
  }
  function fadeOut(voice, fade) {
    const t = S.ctx.currentTime;
    try {
      voice.g.gain.cancelScheduledValues(t);
      voice.g.gain.setValueAtTime(voice.g.gain.value, t);
      voice.g.gain.linearRampToValueAtTime(0.0001, t + fade);
      voice.src.stop(t + fade + 0.05);
    } catch {}
    S.voices = S.voices.filter((x) => x !== voice);
    if (debug && voice.end > t) {
      S.fading = S.fading.filter((x) => x.until > t);
      S.fading.push({ id: voice.id, g: voice.g, until: Math.min(voice.end, t + fade), fade });
    }
  }
  // A bus steps back for a while: down by `db` from `at` s, held, then back.
  function duck(bus, db, { at = 0, attack = 0.05, hold = 0.6, release = 0.5 } = {}) {
    if (!S.ctx || !S.ducks[bus]) return;
    const g = S.ducks[bus].gain;
    const t = S.ctx.currentTime + at;
    g.cancelScheduledValues(S.ctx.currentTime);
    g.setValueAtTime(g.value, S.ctx.currentTime);
    g.setValueAtTime(g.value, t);
    g.linearRampToValueAtTime(dbGain(db), t + attack);
    g.setValueAtTime(dbGain(db), t + attack + hold);
    g.linearRampToValueAtTime(S.idle && bus === "amb" ? 0.0001 : 1, t + attack + hold + release);
  }
  function unduck(bus, release = 1.2) {
    if (!S.ctx || !S.ducks[bus]) return;
    const g = S.ducks[bus].gain, t = S.ctx.currentTime;
    g.cancelScheduledValues(t);
    g.setValueAtTime(g.value, t);
    g.linearRampToValueAtTime(S.idle && bus === "amb" ? 0.0001 : 1, t + release);
  }
  const busy = (s) => (S.hold = Math.max(S.hold, now() + s));
  // a foreground sound now holds the floor for `s` seconds (spot sounds wait for it)
  const foreground = (s) => (S.fgUntil = Math.max(S.fgUntil, now() + s));
  const input = () => {
    S.lastInput = now();
    if (S.idle) wake();
  };

  // ---------------------------------------------------------------- the bed
  function loopSource(id, level, fadeIn) {
    const v = MANIFEST[id]?.variants?.[0];
    const f = v && S.files.get(v.file);
    if (!f?.buffer || !S.ctx) return null;
    const ctx = S.ctx;
    const src = ctx.createBufferSource();
    src.buffer = f.buffer;
    src.loop = true;
    src.loopStart = 0;
    src.loopEnd = Math.min(v.dur || f.buffer.duration, f.buffer.duration); // the mastered length, not the container's padding
    // the file's make-up (a bed kept as generated, under the common level) on a gain of its own
    const up = ctx.createGain();
    up.gain.value = dbGain(makeUp(v, level, true));
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0001, ctx.currentTime);
    g.gain.linearRampToValueAtTime(dbGain(level), ctx.currentTime + fadeIn);
    src.connect(up).connect(g).connect(S.buses.amb);
    src.start(ctx.currentTime, Math.random() * src.loopEnd * 0.8); // never the same opening twice
    return { file: v.file, src, g, level };
  }
  function stopLoop(L, fade) {
    if (!L?.g) return; // a bed still loading has nothing to stop
    const t = S.ctx.currentTime;
    L.g.gain.cancelScheduledValues(t);
    L.g.gain.setValueAtTime(L.g.gain.value, t);
    L.g.gain.linearRampToValueAtTime(0.0001, t + fade);
    try { L.src.stop(t + fade + 0.1); } catch {}
  }
  let bedToken = 0;
  // the bed `loop` (an id of sounds.js); the same one carries on untouched, another crosses over
  // in `fade` seconds (the old one fading out as the new one fades in)
  function setBed(loop, fade = BED_FADE) {
    S.want = loop || null;
    if ((S.bed?.loop || null) === (loop || null)) return;
    const token = ++bedToken;
    stopLoop(S.bed, fade);
    S.bed = loop && MANIFEST[loop] ? { loop, pending: true } : null;
    if (!S.bed) return;
    const level = loop === ROOM.loop ? BED_DB.room : BED_DB.place;
    load(filesOf(loop)[0], true).then(() => {
      // the sound turned off or not unlocked yet: restartBed brings it up then. A tab hidden while it
      // loaded does not hold it back: the context is suspended, it fades in once the tab is back
      if (token !== bedToken || !S.on || !S.unlocked) return;
      const L = loopSource(loop, level, fade);
      if (L) S.bed = { ...L, loop, since: now() };
    });
    log("bed", loop, `${fade} s`);
  }
  // the bed (and the spot sounds) of where the reader is, brought up now (the first touch, sound back
  // on): the one playing carries on if it is still the one wanted; one the reader has left while the
  // sound was off gives way at once (under the master coming back up), never left under the new one
  function restartBed(fade = 3) {
    const scene = S.spot ? sceneFor(S.spot.tale, S.spot.page, S.spot.resolved) : { bed: ROOM.loop, spots: [] };
    const want = S.want || scene.bed;
    if (S.bed?.loop !== want || !S.bed.g) {
      stopLoop(S.bed, 0.3); // a bed still loading has nothing to stop: it is simply asked for again
      S.bed = null;
    }
    setBed(want, fade);
    scheduleSpots(want === scene.bed ? scene.spots : []); // no room spots under an opening's place
  }
  function checkIdle() {
    if (S.idle || !S.ctx || now() - S.lastInput < IDLE_AFTER) return;
    S.idle = true;
    const g = S.ducks.amb.gain, t = S.ctx.currentTime;
    g.cancelScheduledValues(t);
    g.setValueAtTime(g.value, t);
    g.linearRampToValueAtTime(0.0001, t + 8);
    log("idle: the bed fades");
  }
  function wake() {
    S.idle = false;
    if (!S.ctx) return;
    const g = S.ducks.amb.gain, t = S.ctx.currentTime;
    g.cancelScheduledValues(t);
    g.setValueAtTime(g.value, t);
    g.linearRampToValueAtTime(1, t + 3);
  }

  // ---------------------------------------------------------------- spot sounds: part of the place
  // Scheduled after the page has settled, each once (or a few times, far apart); one waits while
  // anything else sounds, including another spot.
  function scheduleSpots(list = []) {
    stopSpots(0);
    for (const spec of list) {
      if (!MANIFEST[spec.id]) continue;
      const sp = { ...spec, plays: 0, due: 0, timer: 0 };
      const arm = (sec) => {
        sp.due = now() + sec;
        sp.timer = setTimeout(fire, sec * 1000);
      };
      const fire = () => {
        if (!ready() || S.idle) return arm(rnd(20, 40));
        if (now() < S.fgUntil + 1.5) return arm(rnd(3, 7)); // something else is sounding: a little later
        const h = play(spec.id, { bus: "amb", pan: rnd(-0.45, 0.45), gainDb: spec.db || 0, late: 0.5 });
        if (h) {
          S.spotVoices.push(h);
          foreground((h.dur || 2) + 0.5);
          log("spot", spec.id);
        }
        sp.plays++;
        if (sp.again && sp.plays < sp.max) arm(rnd(...sp.again));
        else sp.due = 0;
      };
      arm(rnd(...spec.first));
      S.spots.push(sp);
    }
  }
  function stopSpots(fade = 0.4) {
    for (const sp of S.spots) clearTimeout(sp.timer);
    S.spots = [];
    for (const h of S.spotVoices) h.stop(fade);
    S.spotVoices = [];
  }

  // ---------------------------------------------------------------- themes
  // A tale's theme: the first of `ids` that is mastered, from `when` s; the bed steps back for it
  // (themeDuck) and the spot sounds wait for it. `ring`: it rings on to its end across the turns of
  // tale `tale` (an opening theme). Returns whether it plays.
  const THEME_LATE = 2; // s a theme still loading may start late
  function playTheme(ids, when, key, { tale = null, ring = false } = {}) {
    const id = ids.find((x) => MANIFEST[x]);
    if (!id) return false;
    const last = S.themesHeard.get(key) || -1e9;
    if (now() - last < THEME_COOLDOWN) return false;
    if (S.theme) stopTheme(); // another theme still sounding gives way
    const h = play(id, { when, late: THEME_LATE, keep: true });
    if (!h) return false;
    S.themesHeard.set(key, now());
    const dur = MANIFEST[id].variants[0].dur || 10;
    const T = (S.theme = { h, id, tale, ring, at: S.ctx.currentTime + 0.005 + when, dur });
    // the bed steps back from just before the theme sounds (context time `from`) to just before its end
    const duckFrom = (from) => {
      const at = Math.max(0, from - 0.5 - S.ctx.currentTime);
      duck("amb", BED_DB.themeDuck, { at, attack: 1.5, hold: Math.max(0.5, from + dur - 1 - (S.ctx.currentTime + at + 1.5)), release: 3 });
    };
    foreground(when + dur + 1);
    duckFrom(T.at);
    // A theme still loading starts once decoded (up to THEME_LATE s late) or never: the floor and the
    // duck follow it from when it actually sounds (the opening too, startOpening); one that never
    // comes gives way at once, the bed as it would be without a theme.
    h.started.then((voice) => {
      if (S.theme !== T) return; // it has given way meanwhile (stopTheme saw to the bed)
      if (!voice) {
        log("theme never came", id);
        return stopTheme(0);
      }
      if (voice.at - T.at < 0.05) return; // on time
      T.at = voice.at;
      foreground(voice.end - S.ctx.currentTime + 1);
      duckFrom(voice.at);
    });
    log("theme", id, ring ? "(rings on)" : "");
    return true;
  }
  // how long the theme still sounds (s; while it is still loading, as long as it may still start)
  function themeLeft() {
    const T = S.theme;
    if (!T || T.h.cancelled || !S.ctx) return 0;
    const t = S.ctx.currentTime;
    if (T.h.voice) return Math.max(0, T.h.voice.end - t);
    return t <= T.at + THEME_LATE ? T.at + T.dur - t : 0;
  }
  // the theme gives way: faded over `fade` s, the bed back up, the spot sounds no longer held for it
  // (whether it was sounding, still loading or already over: its duck was set as it was asked for,
  // and a duck already released is only ramped from where it is to where it is)
  function stopTheme(fade = THEME_FADE) {
    clearOpening();
    if (!S.theme) return;
    S.theme.h.stop(fade);
    S.theme = null;
    S.fgUntil = Math.min(S.fgUntil, now() + fade);
    unduck("amb", Math.max(2, fade));
    log("theme fades", `${fade} s`);
  }
  // The opening of a tale (soundscape.js): `spec.at` s into its theme (S.theme, just asked for), as
  // it actually sounds (one still loading starts late), the place of its first page rises beneath it
  // over `spec.rise` s, taking over from the hearth; the theme's duck keeps it under the music until
  // the theme ends, then it settles. A theme that never comes: no rise (playTheme stops it).
  function startOpening(tale, spec) {
    clearOpening();
    const T = S.theme;
    if (!T || !spec?.bed || !MANIFEST[spec.bed]) return;
    const op = { tale, bed: spec.bed, risen: false, timer: 0, due: 0 };
    const rise = () => {
      if (S.opening !== op) return;
      // the reader has gone on into the tale (that page's bed is already set), or the theme is over
      if (S.spot?.tale !== tale || S.spot?.page || themeLeft() <= 0) return;
      // a hidden tab (or a context iOS has interrupted): once it is back
      if (!ready() || S.ctx.state !== "running") return void (op.timer = setTimeout(rise, 1000));
      // its moment in the music (context time: a hidden tab pauses the music, and the wait with it)
      const wait = op.due - S.ctx.currentTime;
      if (wait > 0.05) return void (op.timer = setTimeout(rise, wait * 1000));
      op.risen = true;
      stopSpots(0.5); // the room's candle gives way to the place
      setBed(op.bed, spec.rise);
      log("opening: the place rises", op.bed);
    };
    S.opening = op;
    T.h.started.then((voice) => {
      if (S.opening !== op || !voice) return;
      op.due = voice.at + spec.at;
      rise();
    });
  }
  function clearOpening() {
    if (S.opening) clearTimeout(S.opening.timer);
    S.opening = null;
  }

  // ---------------------------------------------------------------- the book's events
  const api = {
    supported,
    attach,
    unlock,
    isEnabled: () => S.on,
    setEnabled(on) {
      S.on = Boolean(on);
      onChange?.(S.on);
      if (S.on) {
        api.preloadCore();
        unlock(); // called from the toggle's click, itself a gesture
        if (S.ctx) {
          const g = S.master.gain, t = S.ctx.currentTime;
          g.cancelScheduledValues(t);
          g.setValueAtTime(g.value, t);
          g.linearRampToValueAtTime(1, t + 0.6);
          restartBed(2); // where the reader is now: turns, tales, "Begin again" while it was off
        }
      } else if (S.ctx) {
        const g = S.master.gain, t = S.ctx.currentTime;
        g.cancelScheduledValues(t);
        g.setValueAtTime(g.value, t);
        g.linearRampToValueAtTime(0, t + 0.3);
        stopSpots(0.2);
        stopTheme(0.3); // with the master: it does not pick up mid-phrase when the sound comes back
        setTimeout(() => !S.on && S.ctx.suspend().catch(() => {}), 450); // a silent book costs no battery
      }
    },
    play,
    duck,
    // hold decoding for `s` seconds (the intro's camera move: a decode on the main thread costs a frame)
    busy,
    // the sounds of every page of the book, decoded ahead (no gesture needed); call once the book's
    // own assets are in, so they never compete with the first picture. The gate's click and the
    // opening cover first, then the room's bed and the turning page: on a slow line the rest
    // arrives while the book opens
    preloadCore: () => S.on && supported && enqueue([...new Set([...FIRST, ROOM.loop, ...groupIds("core"), ...ROOM.spots.map((x) => x.id)])], true),
    preload: (ids) => enqueue(ids),
    preloadTale: (taleId) => enqueue(taleIds(taleId)),
    // the one click of every control (the gate, the language, the arrows, the sound, the tales)
    click() {
      input();
      play("clasp", { bus: "ui" });
    },
    // a leaf turns: only its own quiet sound; the page's spot sounds give way to it, and a closing
    // theme (an opening one rings on to its end: the reader is still in its tale)
    pageTurn(dir = 1, { reduced = false } = {}) {
      input();
      busy(1.3);
      stopSpots(0.3);
      if (!S.theme?.ring) stopTheme();
      if (reduced) play("page-settle");
      else play("page-turn", { pan: 0.25 * dir, panTo: -0.25 * dir, panDur: 0.9 });
      foreground(1.3);
    },
    refusedTurn() {
      input();
      play("page-held");
      foreground(0.7);
    },
    // a choice is sealed: the soft press of the wax and, in the same breath, the harp in D (the
    // first and the last choice of a tale have their own variant); one gesture, nothing after it
    choice({ index = 0, count = 4 } = {}) {
      input();
      const slot = index <= 0 ? "first" : index >= count - 1 ? "last" : "middle";
      play("seal-press");
      play("choice-motif", { when: 0.18, slot, late: 0.4 });
      foreground(2.2);
    },
    // the language switch: the click, and the quill if the spread is rewritten (`rewrite` s)
    language({ rewrite = 0 } = {}) {
      api.click();
      if (rewrite) {
        play("quill-rewrite", { when: 0.12 });
        foreground(rewrite + 0.4);
      }
    },
    // the leaves fly to another tale (or back to a tale's beginning): R = the riffle of main.js
    // ({ starts, durs, dir, total }), `tale` the tale it goes to, `restart` for "Begin again";
    // `reduced`: a crossfade instead. The theme gives way, but for an opening theme whose reader goes
    // back to its own title spread: that one rings on.
    riffle({ starts = [0.14], durs = [1.1], dir = 1, total = 1.3, reduced = false, silk = true, tale = null, restart = false } = {}) {
      input();
      busy(total + 0.4);
      stopSpots(0.3);
      if (restart || !S.theme?.ring || S.theme.tale !== tale) stopTheme();
      foreground(total + 0.5);
      if (silk) play("ribbon-silk");
      if (reduced) return void play("pages-return", { gainDb: -3 });
      const n = starts.length;
      for (let k = 0; k < n - 1; k++) {
        // the leaves between swell and thin out with the riffle
        const shape = -3 * Math.cos(Math.PI * (k / Math.max(1, n - 1))) ** 2;
        play("riffle-leaf", { when: starts[k] + 0.04, gainDb: shape, pan: 0.3 * dir, panTo: -0.3 * dir, panDur: 0.5 });
      }
      // the last leaf turns at the pace of a page and lands
      play("riffle-land", { when: (starts[n - 1] ?? 0) + 0.55, late: 0.3 });
    },
    ribbon() {
      input();
      play("ribbon-silk");
    },
    button: () => api.click(),
    // "Start over": the click of the clasp, then the leaves riffle back to the tale's title (the
    // theme, an opening one too, gives way: the tale begins again)
    startOver(R = null) {
      api.click();
      if (R) api.riffle({ ...R, silk: false, restart: true });
      else {
        stopSpots(0.3);
        stopTheme();
        play("pages-return", { when: 0.15 });
        foreground(1.2);
      }
    },
    // the gate opened: the cover lifts from `delay` s (its landing is coverLand)
    coverOpen({ delay = 0.7 } = {}) {
      S.cover = play("cover-open", { when: delay, late: 0.3 });
      foreground(delay + 3);
    },
    // a tap hurried the opening: the creak gives way, the landing follows the cover
    coverHurry() {
      S.cover?.stop(0.25);
      S.cover = null;
    },
    coverLand() {
      play("cover-land");
    },
    // a spread has come to rest: its bed carries on, or crosses over to the new place's (slowly,
    // from now); its spot sounds are scheduled; a title spread or a tale's last page has its theme,
    // a title spread's opening theme its place rising beneath it (startOpening)
    arrive({ tale, page, resolved = {}, how = "turn" } = {}) {
      S.spot = { tale, page, resolved };
      // the sound off (no theme, no opening then): only the bed it calls for is noted, nothing loads
      if (!S.on || !supported) return void (S.want = sceneFor(tale, page, resolved).bed);
      // another tale's theme still sounding (riffle() fades it; this is only a guard)
      if (S.theme && S.theme.tale !== tale && themeLeft() > 0) stopTheme();
      const scene = sceneFor(tale, page, resolved);
      const op = S.opening?.tale === tale && themeLeft() > 0 ? S.opening : null;
      if (!page && op) {
        // back on the title spread while its opening still sounds: the theme rings on (not started
        // again), the place it has drawn the reader into stays; no room spots under it
        setBed(op.bed, BED_FADE);
        op.risen = true;
        scheduleSpots([]);
      } else {
        setBed(scene.bed, how === "load" ? 3 : BED_FADE);
        scheduleSpots(scene.spots);
        const when = page ? 1.2 : 0.6;
        if (scene.theme && how !== "load" && playTheme(scene.theme, when, `${tale}|${page}`, { tale, ring: scene.ring }) && scene.opening) startOpening(tale, scene.opening);
      }
      enqueue(taleIds(tale));
    },
    // for review and QA (window.__sound with ?sound=debug; main.js shows it on screen)
    state: () => ({
      on: S.on, unlocked: S.unlocked, context: S.ctx?.state || "none", format: null, idle: S.idle,
      at: S.spot ? { tale: S.spot.tale, page: S.spot.page } : null, // the spread last come to rest
      bed: S.bed?.loop || null, bedPending: Boolean(S.bed?.pending && !S.bed?.g), room: S.bed?.loop === ROOM.loop,
      bedSince: S.bed?.since ? +S.bed.since.toFixed(2) : null, // when its loop started (a bed carried on keeps it)
      theme: themeLeft() > 0 ? S.theme.id : null, // only while it sounds
      themeLeft: +themeLeft().toFixed(1), themeTale: themeLeft() > 0 ? S.theme.tale : null,
      opening: S.opening ? { tale: S.opening.tale, bed: S.opening.bed, risen: S.opening.risen } : null,
      foreground: +Math.max(0, S.fgUntil - now()).toFixed(1),
      spots: S.spots.filter((sp) => sp.due).map((sp) => ({ id: sp.id, in: +(sp.due - now()).toFixed(1), plays: sp.plays, max: sp.max })),
      mixer: S.ctx ? { master: gainDb(S.master.gain.value), duck: Object.fromEntries(BUSES.map((b) => [b, gainDb(S.ducks[b].gain.value)])), bedLevel: S.bed?.g ? gainDb(S.bed.g.gain.value) : null, themeDb: S.theme?.h.voice && themeLeft() > 0 ? gainDb(S.theme.h.voice.g.gain.value) : null, prePeakDb: S.meter ? +S.meter.pre.toFixed(1) : null, peakDb: S.meter ? +S.meter.post.toFixed(1) : null, limiterThreshold: LIMITER.threshold } : null,
      voices: S.voices.map((v) => v.id),
      fading: S.ctx ? S.fading.filter((x) => x.until > S.ctx.currentTime).map((x) => ({ id: x.id, db: gainDb(x.g.gain.value), fade: x.fade, left: +(x.until - S.ctx.currentTime).toFixed(2) })) : [],
      decodedMB: +([...S.files.values()].reduce((a, f) => a + f.bytes, 0) / 1048576).toFixed(1), files: S.files.size,
      queued: S.queue.length, decoded: debug ? [...S.files.entries()].filter(([, f]) => f.buffer).map(([k]) => k) : undefined,
    }),
    format: () => formatReady,
    // debug only: the sounds started since `t` (performance seconds), with the file each played
    history: (t = 0) => S.history.filter((h) => h.t >= t),
    now,
  };
  return api;
}
